const e = $input.first().json || {};
const ex = e.execution || {};
const wf = e.workflow || {};
const err = ex.error || {};

function fnv(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(16).padStart(8, "0");
}

// The Error Trigger does not hand us the failing run\u2019s input, so the
// trace id and tenant are only recoverable when the message carries them.
// Rather than guess, record what is known and mark the rest unknown: a
// dead-letter row that lies about its scope is worse than one that admits
// it. The execution URL is always enough for a human to recover the input.
const blob = JSON.stringify(e);
const traceMatch = blob.match(/"trace_id"\s*:\s*"([^"]{1,64})"/);
const tenantMatch = blob.match(/"tenant_id"\s*:\s*"([a-z0-9][a-z0-9_-]{0,62})"/);

const message = String(err.message || "no message supplied by the error trigger");
const failureId = "f-" + String(ex.id || "unknown") + "-" + fnv(message + String(ex.lastNodeExecuted || ""));

return [{ json: {
  failure_id: failureId,
  trace_id: traceMatch ? traceMatch[1] : "",
  tenant_id: tenantMatch ? tenantMatch[1] : "",
  workflow_id: String(wf.id || ""),
  workflow_name: String(wf.name || "unknown"),
  node_name: String(ex.lastNodeExecuted || "unknown"),
  error_message: message.slice(0, 1000),
  error_detail: String(err.stack || err.description || "").slice(0, 3000),
  execution_id: String(ex.id || ""),
  execution_url: String(ex.url || ""),
  execution_mode: String(ex.mode || "unknown"),
  replay_payload: "",
  replayable: false,
  status: "new"
} }];

const req = $input.first().json || {};

function parseJson(v, fallback) {
  if (v && typeof v === "object") { return v; }
  if (typeof v === "string" && v.trim()) {
    try { return JSON.parse(v); } catch (e) { return fallback; }
  }
  return fallback;
}

const rawTenant = String(req.tenant_id || "default").trim().toLowerCase();
const tenantId = /^[a-z0-9][a-z0-9_-]{0,62}$/.test(rawTenant) ? rawTenant : "";
const lead = parseJson(req.lead, {});
const options = parseJson(req.options, {});

// A replay is a deliberate re-run of a lead the pipeline already saw, so
// force is set: without it the ledger would suppress it as a duplicate and
// the replay would silently do nothing. dry_run is still whatever the
// caller asks for, and still defaults to true.
options.force = true;
options.tenant_id = tenantId;
if (options.dry_run === undefined) { options.dry_run = true; }

const problems = [];
if (!tenantId) { problems.push("tenant_id must match ^[a-z0-9][a-z0-9_-]{0,62}$; got " + JSON.stringify(rawTenant)); }
if (!lead || !lead.email) { problems.push("a replay needs the original lead; supply it as `lead` (the failure row records the execution URL it can be read from)"); }

return [{ json: {
  failure_id: String(req.failure_id || ""),
  tenant_id: tenantId,
  lead_json: JSON.stringify(lead),
  options_json: JSON.stringify(options),
  dry_run: options.dry_run !== false,
  ok: problems.length === 0,
  problems: problems,
  started_at_ms: Date.now()
} }];

const req = $("Normalise Replay").first().json;
const raw = $input.first().json;
const r = (raw && raw.json) ? raw.json : raw;
return [{ json: {
  failure_id: req.failure_id,
  tenant_id: req.tenant_id,
  replayed: true,
  outcome: r.outcome || "unknown",
  trace_id: r.trace_id || "",
  dry_run: req.dry_run,
  result: r,
  problems: [],
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

const req = $("Normalise Replay").first().json;
return [{ json: {
  failure_id: req.failure_id,
  tenant_id: req.tenant_id,
  replayed: false,
  outcome: "replay_refused",
  trace_id: "",
  dry_run: req.dry_run,
  result: {},
  problems: req.problems,
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

const SOURCES = ["Capture Replay", "Reject Replay"];
for (const name of SOURCES) {
  try {
    const items = $(name).all();
    if (items && items.length) { return [{ json: items[0].json }]; }
  } catch (e) { }
}
return [{ json: { replayed: false, outcome: "no_branch_ran", problems: ["wiring bug: no replay branch produced a result"] } }];

// Signals are supplied so a replay costs no model call and lands on a known
// tier. dry_run stays true: a replay must never be a licence to write.
const nonce = String($execution.id) + Date.now().toString(36);

const SIGNALS = JSON.stringify({
  seniority: "executive", decision_authority: "decision_maker", company_size_band: "201-1000",
  budget_signal: "explicit", timeline: "immediate", pain_specificity: "specific",
  use_case_fit: "core", competitor_mentioned: false, evidence: []
});

function opts(extra) {
  return JSON.stringify(Object.assign({
    dry_run: true,
    enrich: false,
    channel: "email",
    simulate_decision: "approve",
    signals_override: SIGNALS
  }, extra || {}));
}

const fixtures = [
  { case_id: "R01", note: "a valid replay reaches the orchestrator and is processed",
    failure_id: "f-test-" + nonce, tenant_id: "acme",
    lead: JSON.stringify({ email: "replay-" + nonce + "@analytical.io", job_title: "CTO", company_name: "Analytical Engines", message: "We have 30k set aside." }),
    options: opts(), expect_replayed: true, expect_outcome: "processed" },
  { case_id: "R02", note: "a replay with no lead is refused with a reason",
    failure_id: "f-test-" + nonce + "-b", tenant_id: "acme",
    lead: "", options: opts(), expect_replayed: false, expect_outcome: "replay_refused" },
  { case_id: "R03", note: "a malformed tenant is refused before anything is replayed",
    failure_id: "f-test-" + nonce + "-c", tenant_id: "acme:globex",
    lead: JSON.stringify({ email: "replay-c-" + nonce + "@analytical.io" }),
    options: opts(), expect_replayed: false, expect_outcome: "replay_refused" }
];

return fixtures.map(function (f) { return { json: f }; });

const raw = $input.first().json;
const r = (raw && raw.json) ? raw.json : raw;
const fx = $("Replay Fixture Loop").first().json;
return [{ json: {
  case_id: fx.case_id,
  note: fx.note,
  expect_replayed: fx.expect_replayed,
  expect_outcome: fx.expect_outcome,
  actual_replayed: r.replayed === true,
  actual_outcome: r.outcome,
  problems: r.problems || [],
  trace_id: r.trace_id || "",
  dry_run: r.dry_run,
  latency_ms: r.latency_ms
} }];

const rows = $input.all().map(function (i) { return i.json; });

const cases = rows.map(function (r) {
  const checks = [];
  checks.push({ name: "replayed", pass: r.actual_replayed === r.expect_replayed, expected: r.expect_replayed, actual: r.actual_replayed });
  checks.push({ name: "outcome", pass: r.actual_outcome === r.expect_outcome, expected: r.expect_outcome, actual: r.actual_outcome });
  checks.push({ name: "replay_stays_dry", pass: r.dry_run === true, expected: true, actual: r.dry_run });
  if (!r.expect_replayed) {
    checks.push({ name: "refusal_explained", pass: (r.problems || []).length > 0, expected: ">0 problems", actual: (r.problems || []).length });
  } else {
    checks.push({ name: "trace_recorded", pass: String(r.trace_id || "").length > 0, expected: "a trace id", actual: r.trace_id });
  }
  const failed = checks.filter(function (c) { return !c.pass; });
  return { case_id: r.case_id, note: r.note, passed: failed.length === 0, checks: checks, latency_ms: r.latency_ms };
});

const passed = cases.filter(function (c) { return c.passed; }).length;
return [{ json: {
  suite: "16-failure-handler",
  run_at: new Date().toISOString(),
  execution_id: $execution.id,
  total: cases.length,
  passed: passed,
  failed: cases.length - passed,
  all_passed: passed === cases.length && cases.length === 3,
  cases: cases
} }];
